  function parseCronField(field,min,max,names){
    const out=[];
    field.split(',').forEach(part=>{
      let m=part.match(/^\*\/(\d+)$/);if(m){for(let i=min;i<=max;i+=(+m[1]||1))out.push(i);return;}
      m=part.match(/^(\d+|\*)-(\d+)(?:\/(\d+))?$/);
      if(m){const a=m[1]==='*'?min:+m[1],b=+m[2],st=+(m[3]||1);for(let i=a;i<=Math.min(b,max);i+=st)out.push(i);return;}
      if(part==='*'){for(let i=min;i<=max;i++)out.push(i);return;}
      const n=part.toUpperCase();
      if(names&&names[n]!==undefined)out.push(names[n]);
      else if(!isNaN(+part)&&+part>=min&&+part<=max)out.push(+part);
    });
    return [...new Set(out)].sort((a,b)=>a-b);
  }
  const DOW={SUN:0,MON:1,TUE:2,WED:3,THU:4,FRI:5,SAT:6};
  R('CRON 表达式生成解析', { fields:[I('cron','CRON 表达式','*/15 9-18 * * 1-5'),N('count','计算未来执行次数',5)],live:true,
    run:v=>{
      const parts=String(v.cron||'').trim().split(/\s+/);
      if(parts.length<5||parts.length>7)return {type:'note',kind:'err',value:'CRON 表达式应为 5~7 个字段：分 时 日 月 周 [年] [秒]'};
      const [mi,hh,dd,mo,dow]=parts;
      let mins,hours,days,months,dows;
      try{mins=parseCronField(mi,0,59);hours=parseCronField(hh,0,23);days=parseCronField(dd,1,31);months=parseCronField(mo,1,12);dows=parseCronField(dow,0,7,DOW);}
      catch(e){return {type:'note',kind:'err',value:'解析失败：'+T.esc(e.message)};}
      const desc=()=>{
        const f=(a,names)=>a.length>12?'每'+'':a.join(',');
        return `分钟 ${f(mins)} · 小时 ${f(hours)} · 日 ${dd==='*'?'每天':days.join(',')} · 月 ${mo==='*'?'每月':months.join(',')} · 星期 ${dow==='*'?'每天':dows.map(d=>'日一二三四五六'[d%7]).join('')}`;
      };
      const next=[],start=new Date();start.setSeconds(0,0);start.setMinutes(start.getMinutes()+1);
      let cur=new Date(start),guard=0;
      const want=T.clamp(Math.round(Number(v.count)||5),1,20);
      while(next.length<want&&guard++<600000){
        if(months.includes(cur.getMonth()+1)&&hours.includes(cur.getHours())&&mins.includes(cur.getMinutes())&&
          (dd==='*'||days.includes(cur.getDate()))&&(dow==='*'||dows.includes(cur.getDay())||dows.includes(7)&&cur.getDay()===0)){
          next.push(new Date(cur));cur=new Date(cur.getTime()+60000);continue;
        }
        cur=new Date(cur.getTime()+60000);
      }
      const preset=[['0 0 * * *','每天 0 点'],['0 9 * * 1-5','工作日早 9 点'],['*/5 * * * *','每 5 分钟'],['0 0 1 * *','每月 1 号 0 点'],['30 2 * * 0','每周日 2:30'],['0 */2 * * *','每 2 小时'],['0 0 * * 1','每周一 0 点'],['*/30 9-18 * * *','9:00-18:59 每半小时']];
      return [KV([['表达式',parts.join(' ')],['字段数',parts.length+(parts.length===6?'（含秒或年）':'')],['含义',desc()],['分钟取值数',mins.length],['小时取值数',hours.length]],'CRON 解析'),
        {type:'table',title:`未来 ${want} 次执行时间（本地时区）`,head:['#','时间','星期'],rows:next.map((d,i)=>[i+1,d.toLocaleString('zh-CN'),'星期'+'日一二三四五六'[d.getDay()]])},
        {type:'table',title:'常用表达式速查',head:['表达式','说明'],rows:preset}];} });

