  R('RSA 密钥生成', { fields:[S('bits','密钥长度',[['2048','2048 位'],['3072','3072 位'],['4096','4096 位']],'2048')],runLabel:'生成新密钥对',
    run:async v=>{
      const bits=Number(v.bits)||2048;
      const kp=await crypto.subtle.generateKey({name:'RSA-OAEP',modulusLength:bits,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},true,['encrypt','decrypt']);
      const pem=(buf,label)=>`-----BEGIN ${label}-----\n${b64(buf).match(/.{1,64}/g).join('\n')}\n-----END ${label}-----\n`;
      const pub=pem(await crypto.subtle.exportKey('spki',kp.publicKey),'PUBLIC KEY');
      const pri=pem(await crypto.subtle.exportKey('pkcs8',kp.privateKey),'PRIVATE KEY');
      return [{type:'text',value:pub,title:'公钥 PEM',download:'public.pem'},
        {type:'text',value:pri,title:'私钥 PEM（请妥善保管，不要外传）',download:'private.pem'},
        {type:'note',kind:'warn',value:`密钥对由浏览器 Web Crypto 在本地生成，页面刷新后不会保留。已生成 ${bits} 位 RSA-OAEP（SHA-256）密钥，可用于加密或签名场景。`}];} });

