  function yamlToObj(text){
    const lines=text.split(/\r?\n/).filter(l=>l.trim()&&!l.trim().startsWith('#'));
    const root={},stack=[{indent:-1,obj:root}];
    lines.forEach(line=>{
      const m=line.match(/^(\s*)([^:]+):\s*(.*)$/);
      if(!m)return;
      const indent=m[1].length,key=m[2].trim().replace(/^['"]|['"]$/g,''),val=m[3].trim();
      while(stack.length>1&&stack[stack.length-1].indent>=indent)stack.pop();
      const parent=stack[stack.length-1].obj;
      if(val===''){const o={};parent[key]=o;stack.push({indent,obj:o});}
      else{
        let v=val.replace(/\s+#.*$/,'').replace(/^['"]|['"]$/g,'');
        if(v==='true')v=true;else if(v==='false')v=false;else if(v==='null'||v==='~')v=null;
        else if(/^-?\d+(\.\d+)?$/.test(v))v=Number(v);
        else if(/^\[.*\]$/.test(v))v=v.slice(1,-1).split(',').map(x=>x.trim().replace(/^['"]|['"]$/g,'')).filter(Boolean);
        parent[key]=v;
      }
    });
    return root;
  }
  R('YAML 校验格式化', { fields:[X('text','YAML 内容','name: 拾器 ToolBox\nversion: 1.0.0\nlocal: true\ntools:\n  image: 29\n  dev: 34\ntags:\n  - pdf\n  - qrcode'),S('mode','操作',[['json','YAML → JSON'],['check','仅校验'],['indent','重新缩进']],'json')],live:true,
    run:v=>{
      const s=String(v.text||'');
      const lines=s.split(/\r?\n/),errs=[];
      lines.forEach((l,i)=>{if(l.includes('\t'))errs.push(`第 ${i+1} 行含 Tab（YAML 只允许空格缩进）`);
        if(l.trim()&&!l.trim().startsWith('#')&&!l.trim().startsWith('-')&&!/^\s*[^:]+:/.test(l))errs.push(`第 ${i+1} 行不是合法键值`);});
      const obj=yamlToObj(s);
      if(errs.length)return {type:'note',kind:'warn',value:'发现 '+errs.length+' 处问题：<br>'+errs.map(T.esc).join('<br>')};
      if(v.mode==='check')return KV([['校验结果','语法基本合法'],['顶层键',Object.keys(obj).join(', ')],['行数',lines.length]],'YAML 校验');
      if(v.mode==='json')return TXT(JSON.stringify(obj,null,2),'转换后的 JSON','data.json');
      return TXT(lines.map(l=>l.replace(/\t/g,'  ')).join('\n'),'格式化结果','data.yaml');} });

  R('TOML 格式化', { fields:[X('text','TOML 内容','title = "拾器 ToolBox"\n[site]\nname = "tools"\nlocal = true\ncount = 260\n[tags]\nlist = ["pdf", "qrcode", "image"]'),S('mode','操作',[['json','TOML → JSON'],['check','仅校验']],'json')],live:true,
    run:v=>{
      const s=String(v.text||''),obj={},errs=[];let cur=obj;
      s.split(/\r?\n/).forEach((line,i)=>{
        const l=line.trim();if(!l||l.startsWith('#'))return;
        const sec=l.match(/^\[([^\]]+)\]$/);
        if(sec){cur=obj;sec[1].split('.').forEach(k=>{cur[k]=cur[k]||{};cur=cur[k];});return;}
        const kv=l.match(/^([\w.-]+)\s*=\s*(.+)$/);
        if(!kv){errs.push(`第 ${i+1} 行无法解析：${l}`);return;}
        let val=kv[2].trim();
        if(/^".*"$/.test(val)||/^'.*'$/.test(val))val=val.slice(1,-1);
        else if(/^(true|false)$/.test(val))val=val==='true';
        else if(/^-?\d+(\.\d+)?$/.test(val))val=Number(val);
        else if(/^\[.*\]$/.test(val))val=val.slice(1,-1).split(',').map(x=>x.trim().replace(/^["']|["']$/g,'')).filter(Boolean);
        cur[kv[1]]=val;
      });
      if(errs.length)return {type:'note',kind:'warn',value:''+errs.map(T.esc).join('<br>')};
      if(v.mode==='check')return KV([['校验结果','基本合法'],['顶层键',Object.keys(obj).join(', ')]],'TOML 校验');
      return [TXT(JSON.stringify(obj,null,2),'转换后的 JSON','data.json'),{type:'note',value:'内置轻量解析器，支持字符串 / 数字 / 布尔 / 数组 / 表（[section]）；复杂内联表与多行字符串请使用专业库。'}];} });

  R('颜色渐变生成器', { fields:[I('c1','起始颜色','#7c6cff',{type:'color'}),I('c2','结束颜色','#4ea8ff',{type:'color'}),N('angle','角度（度）',120),S('type','渐变类型',[['linear','线性 linear-gradient'],['radial','径向 radial-gradient']],'linear'),N('stops','色标数量',2)],live:true,
    run:v=>{
      const [r1,g1,b1]=hex2rgbLocal(v.c1),[r2,g2,b2]=hex2rgbLocal(v.c2),n=T.clamp(Math.round(Number(v.stops)||2),2,8);
      const mix=(a,b,t)=>Math.round(a+(b-a)*t).toString(16).padStart(2,'0');
      const stops=Array.from({length:n},(_,i)=>{const t=i/(n-1);return `#${mix(r1,r2,t)}${mix(g1,g2,t)}${mix(b1,b2,t)} ${Math.round(t*100)}%`;});
      const css=v.type==='linear'?`linear-gradient(${v.angle}deg, ${stops.join(', ')})`:`radial-gradient(circle, ${stops.join(', ')})`;
      return [{type:'html',title:'渐变预览',value:`<div style="height:150px;border-radius:10px;background:${css};border:1px solid var(--line)"></div>`},
        TXT(`background: ${css};`,'CSS 代码','gradient.css'),
        TXT(stops.map(s=>s.split(' ')[0]).join('\n'),'色标色值','stops.txt')];} });
  function hex2rgbLocal(h){h=h.replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');if(!/^[0-9a-f]{6}$/i.test(h))throw new Error('色值格式错误');return[parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];}

